# Universal traversal: one interface (list/stat/read) dispatched per storage backend.
class MemFS:
    kind = "mem"
    def __init__(self, tree): self.tree = tree
    def _node(self, path):
        node = self.tree
        for p in path.strip("/").split("/"):
            if p:
                if not isinstance(node, dict) or p not in node:
                    raise LookupError("NotFound: " + path)
                node = node[p]
        return node
    def list(self, path):
        n = self._node(path)
        return sorted(n) if isinstance(n, dict) else []
    def read(self, path):
        n = self._node(path)
        return n if isinstance(n, str) else None
class ZipFS:
    kind = "zip"
    def __init__(self, members): self.members = members
    def list(self, path):
        p = path.strip("/") + ("/" if path.strip("/") else "")
        out = set()
        for m in self.members:
            if m.startswith(p):
                rest = m[len(p):]
                out.add(rest.split("/")[0] + ("/" if "/" in rest else ""))
        return sorted(out)
    def read(self, path): return self.members.get(path.strip("/"))
backends = {"mem": MemFS({'docs': {'a.txt': 'hi'}}), "zip": ZipFS({'z/a.txt': 'yo'})}
def ls(uri):
    scheme, _, path = uri.partition("://")
    be = backends[scheme]
    try:
        print(f"{uri} [{be.kind}] -> {be.list(path)}")
    except LookupError as e:
        print(f"{uri} [{be.kind}] -> unified error: {e}")
for u in ['mem://docs', 'zip://']: ls(u)
def first_file(tree, prefix=""):
    for k, v in sorted(tree.items()):
        if isinstance(v, dict):
            r = first_file(v, prefix + k + "/")
            if r: return r
        else:
            return prefix + k
    return None
mf = first_file({'docs': {'a.txt': 'hi'}})
print("read", mf, ":", backends["mem"].read(mf) if mf else "n/a (no files)")

